#!/usr/bin/env bash
# to-be = 등재된 구현 대상. docs/session-mcp-tool-surface.md 의 「다음에 구현할 도구」 절이
# 갖는 `### ` 항목 목록만 본다 → 같은 파일의 다른 문단(규칙·경계·산문)이 바뀌어도 움직이지 않는다.
# 런타임이 dataSource.repository(dlddu/session-platform)@ref(main)를 체크아웃한 상태를 가정한다.
set -euo pipefail
doc=docs/session-mcp-tool-surface.md
[ -f "$doc" ] || { echo "missing $doc — 등재 문서가 옮겨졌다. 모델 개정 필요." >&2; exit 1; }
grep -q '^## 다음에 구현할 도구' "$doc" || {
  echo "roadmap heading not found in $doc — 절이 개명·재구성됐다. 모델 개정 필요." >&2; exit 1; }
entries="$(awk '
  /^## 다음에 구현할 도구/ { inside=1; next }
  inside && /^## / { inside=0 }
  inside && /^### / { sub(/^### +/,""); gsub(/`/,""); gsub(/[[:space:]]+$/,""); print }
' "$doc")"
if [ -z "$entries" ]; then printf 'roadmap:0\n'; exit 0; fi
count="$(printf '%s\n' "$entries" | wc -l | tr -d ' ')"
printf 'roadmap:%s %s\n' "$count" "$(printf '%s\n' "$entries" | paste -sd'|' -)"

#!/usr/bin/env python3
# as-is = 실제 도구 표면. data-plane/cmd/agent 의 toolDefinitions() 본문이 내는 도구 이름만 뽑는다
# → 같은 패키지의 다른 변경(게이트 내부·파일 스풀·notice 등)은 움직이지 않는다.
# 런타임이 dataSource.repository(dlddu/session-platform)@ref(main)를 체크아웃한 상태를 가정한다.
import pathlib, re, sys

pkg = pathlib.Path("data-plane/cmd/agent")
src_path = pkg / "session_mcp_tools.go"
if not src_path.is_file():
    sys.exit("missing %s — 도구 표면의 정본이 옮겨졌다. 모델 개정 필요." % src_path)
src = src_path.read_text(encoding="utf-8")

m = re.search(r"func \([^)]*\) toolDefinitions\(\)[^{]*\{", src)
if not m:
    sys.exit("toolDefinitions() not found — 표면 추출이 구조를 잃었다. 모델 개정 필요.")
start = m.end() - 1
depth = 0
end = None
for i in range(start, len(src)):
    if src[i] == "{":
        depth += 1
    elif src[i] == "}":
        depth -= 1
        if depth == 0:
            end = i
            break
if end is None:
    sys.exit("toolDefinitions() body not balanced — 모델 개정 필요.")
body = src[start : end + 1]

raw = re.findall(r'"name"\s*:\s*("[^"]*"|[A-Za-z_][A-Za-z0-9_]*)', body)

consts = {}
for f in sorted(pkg.glob("*.go")):
    for k, v in re.findall(
        r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"([^"]*)"\s*$',
        f.read_text(encoding="utf-8"),
        re.M,
    ):
        consts.setdefault(k, v)

names = []
for n in raw:
    if n.startswith('"'):
        names.append(n[1:-1])
    elif n in consts:
        names.append(consts[n])
    else:
        sys.exit("unresolved tool name identifier %r — 이름이 상수 리터럴이 아니다. 모델 개정 필요." % n)

names = sorted(set(names))
print("tools:%d%s" % (len(names), (" " + ",".join(names)) if names else ""))
